mapper.select:
select gather_site as gatherSite,
pid_route as pidRoute,

    max(temp) as maxData,
    min(temp) as minData,
    round(avg(temp),2) as avgData


    max(humiture) as maxData,
    min(humiture) as minData,
    round(avg(humiture),2) as avgData


    max(oxygen) as maxData,
    min(oxygen) as minData,
    round(avg(oxygen),2) as avgData

from
tb_node_env_history
tb_node_o2_history

    site_type = '05'

        and pid_route like concat(#{gatherSiteRoute},'%')


        and createdTime >=#{acquisitionTimeOne}


        and createdTime <=#{acquisitionTimeTwo}


group by gather_site,pidRoute
having 1=1

    and maxData >=#{valOne}


    and maxData <=#{valTwo}


    and minData >=#{valOne}


    and minData <=#{valTwo}


    and avgData >=#{valOne}


    and avgData <=#{valTwo}

SELECT tneh.temp as tempData,
tneh.humiture as humitureData,
createdTime as createTime,
node_id as nodeId,
gather_site as gatherSite
from tb_node_env_history tneh
WHERE pid_route = #{gatherSiteRoute}

    and createdTime >= #{acquisitionTimeOne}


    and createdTime <= #{acquisitionTimeTwo}

ORDER by createdTime desc

SELECT oxygen as o2Data,
createdTime as createTime,
node_id as nodeId,
gather_site as gatherSite
FROM tb_node_o2_history tnoh
WHERE pid_route = #{gatherSiteRoute}

    and createdTime >= #{acquisitionTimeOne}


    and createdTime <= #{acquisitionTimeTwo}

ORDER by createdTime desc

select gather_site as gatherSiteOne, node_id as nodeIdOne, round(avg(tneh.temp),2) as tempDataOne, round(avg(tneh.humiture),2) as humitureDataOne, toStartOfInterval(createdTime , INTERVAL
#{samplingFrequency}
hour
day
month
year
) as createTime from tb_node_env_history tneh
pid_route = #{gatherSiteRoute}
and createdTime >=#{acquisitionTimeOne}
and createdTime <=#{acquisitionTimeTwo}
group by createTime,gatherSiteOne,nodeIdOne ORDER BY createTime desc

select gather_site as gatherSite,
pid_route as pidRoute,

    max(temp) as maxData,
    min(temp) as minData,
    round(avg(temp),2) as avgData


    max(humiture) as maxData,
    min(humiture) as minData,
    round(avg(humiture),2) as avgData

from
tb_node_env_history


        and pid_route like concat(#{gatherSiteRoute},'%')


        and createdTime >=#{acquisitionTimeOne}


        and createdTime <=#{acquisitionTimeTwo}


group by gatherSite,pidRoute
having 1=1

    and maxData >=#{valOne}


    and maxData <=#{valTwo}


    and minData >=#{valOne}


    and minData <=#{valTwo}


    and avgData >=#{valOne}


    and avgData <=#{valTwo}

select gather_site as gatherSite,

    temp as nowData


    humiture as nowData

from
tb_node_env_history

    createdTime in (select max(createdTime) from tb_node_env_history GROUP BY gather_site)

        and pid_route like concat(#{gatherSiteRoute},'%')


        and createdTime >=#{acquisitionTimeOne}


        and createdTime <=#{acquisitionTimeTwo}


        and nowData >=#{valOne}


        and nowData <=#{valTwo}


order by createdTime desc

SELECT gather_site as gatherSite,
tneh.temp as tempData,
pid_route as pidRoute,
round(avg(tntcch.temp),2) as coreTempData,
round(coreTempData - tempData,2) as differenceValue,
formatDateTime(createdTime,'%F %H:%M') as createTime
FROM tb_node_env_history tneh,
tb_node_temp_core_chip_history tntcch

    site_type = '05'
    and createdTime in (select max(createdTime) from tb_node_env_history  GROUP BY gather_site)

        and pid_route like concat(#{gatherSiteRoute},'%')


        and createdTime >=#{acquisitionTimeOne}


        and createdTime <=#{acquisitionTimeTwo}


group by gather_site,tempData,pidRoute,createTime
having 1=1

    and tempData >=#{valOne}


    and tempData <=#{valTwo}


    and coreTempData >=#{valOne}


    and coreTempData <=#{valTwo}


    and differenceValue >=#{valOne}


    and differenceValue <=#{valTwo}

select gather_site as gatherSiteOne, node_id as nodeIdOne, round(avg(tneh.temp),2) as coreTempDataOne, toStartOfInterval(createdTime , INTERVAL
#{samplingFrequency}
hour
day
month
year
) as createTime from tb_node_temp_core_chip_history tneh
pid_route = #{gatherSiteRoute}
and createdTime >=#{acquisitionTimeOne}
and createdTime <=#{acquisitionTimeTwo}
group by createTime,node_id,gather_site,pid_route order by createTime desc

SELECT
tneh.temp as tempData,
tneh.humiture as humitureData,
tneh.gather_site as gatherSite,
pid_route as pidRoute
from tb_node_env_history tneh

    createdTime in (select max(createdTime) from tb_node_env_history  GROUP BY gather_site)

        and pid_route = #{gatherSiteRoute}


        and tempData >=#{tempOne}


        and tempData <=#{tempTwo}


        and humitureData >=#{humitureOne}


        and humitureData <=#{humitureTwo}


group by gatherSite,tempData,humitureData,tneh.createdTime,pidRoute
order by tneh.createdTime desc

SELECT tnoh.oxygen as o2Data,
tnoh.gather_site as gatherSite,
pid_route as pidRoute
from tb_node_o2_history tnoh

    createdTime in (select max(createdTime) from tb_node_o2_history  GROUP BY gather_site)

        and pid_route = #{gatherSiteRoute}



        and o2Data >=#{o2One}


        and o2Data <=#{o2Two}


group by gatherSite,o2Data,tnoh.createdTime,pidRoute
order by tnoh.createdTime desc

SELECT round(avg(tntcch.temp),2) as coreTempData, tntcch.gather_site as gatherSite, pid_route as pidRoute from tb_node_temp_core_chip_history tntcch
createdTime in (select max(createdTime) from tb_node_temp_core_chip_history GROUP BY gather_site)
and pid_route = #{gatherSiteRoute}
group by gatherSite,tntcch.createdTime,pidRoute having 1 = 1
and coreTempData >=#{coreTempOne}
and coreTempData <=#{coreTempTwo}
order by tntcch.createdTime desc

